import 'package:flutter/material.dart'; import 'package:provider/provider.dart'; import '../providers/tracking_provider.dart'; import '../providers/permission_provider.dart'; import '../widgets/empty_state.dart'; class TrackingPage extends StatefulWidget{const TrackingPage({super.key});@override State<TrackingPage> createState()=>_TrackingPageState();} class _TrackingPageState extends State<TrackingPage>{@override void initState(){super.initState();WidgetsBinding.instance.addPostFrameCallback((_){context.read<TrackingProvider>().start();});}@override void dispose(){context.read<TrackingProvider>().stop();super.dispose();}@override Widget build(BuildContext c){final g=c.watch<TrackingProvider>().latest;final ready=c.watch<PermissionProvider>().ready;if(!ready)return const Scaffold(body:EmptyState(icon:Icons.lock_outline,title:'أكمل الصلاحيات',subtitle:'فعّل المتطلبات أولاً.'));if(g==null)return const Scaffold(body:EmptyState(icon:Icons.visibility_off_outlined,title:'في انتظار بيانات النظر',subtitle:'ابدأ الكاميرا من الشاشة الرئيسية.'));return Scaffold(appBar:AppBar(title:const Text('تتبع النظر')),body:Center(child:Column(mainAxisSize:MainAxisSize.min,children:[const Icon(Icons.visibility,size:64),const SizedBox(height:12),Text('X: '+g.xPx.toStringAsFixed(0)+'  Y: '+g.yPx.toStringAsFixed(0)),Text('Confidence: '+g.confidence.toStringAsFixed(2)),if(g.isBlinking)const Chip(label:Text('Blink'))])));}}